from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # In these examples, 9 marks the diagonal to continue; when absent,
    # continue the clear longest diagonal run of non-background cells.
    target = 9 if any(9 in row for row in grid) else None
    runs = []
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or (target is not None and color != target):
                    continue
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                cells=[]
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    cells.append((rr,cc))
                    rr += dr; cc += dc
                runs.append((len(cells), color, cells, dr, dc, rr, cc))
    if target is None:
        candidates=[x for x in runs if x[0] >= 3]
        if not candidates:
            return out
        best=max(x[0] for x in candidates)
        runs=[x for x in candidates if x[0] == best]
    else:
        runs=[x for x in runs if x[0] >= 2]
    for length,color,cells,dr,dc,rr,cc in runs:
        r,c=cells[0]
        for ar,ac,sr,sc in ((r-dr,c-dc,-dr,-dc),(rr,cc,dr,dc)):
            while 0 <= ar < h and 0 <= ac < w and grid[ar][ac] == bg:
                out[ar][ac]=color
                ar += sr; ac += sc
    return out
